{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Esaxerenone, a high-transfer analogue, showed absolute oral bioavailability of 90.8% in healthy subjects after a 5 mg oral dose versus IV, directly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Quinapril, a high-transfer analogue, had absolute bioavailability of 45.9% in healthy participants after a 20 mg oral dose versus IV quinaprilat, supporting F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Metoprolol, a high-transfer analogue, showed mean oral bioavailability of 0.50 ± 0.11 in healthy subjects, supporting high F at the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Alfuzosin, a high-transfer analogue, had a mean absolute oral bioavailability of 64% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Benazeprilat, measured after oral benazepril, had absolute bioavailability of 27.1–28.5%, still above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a sulfonylurea-type oral small molecule. All high-transfer analogues with direct human absolute bioavailability measurements show F values from about 27% to 90%, consistently above the 20% threshold. No affirmative evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself; prediction relies on high-transfer analogues.",
    "Some analogue records come from special populations or fed/fasting conditions, but the majority are healthy-subject absolute F determinations."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

